import {fontFamilies,escapeXML as esc,textBinding} from './text-editor.js';
const field=(label,key,value,type='number',attrs='')=>`<label><span>${label}</span><input type="${type}" data-prop="${key}" value="${esc(value??'')}" ${attrs}></label>`;
const select=(label,key,value,options)=>`<label><span>${label}</span><select data-prop="${key}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const check=(label,key,value)=>`<label class="toggle-row">${label}<input type="checkbox" data-prop="${key}" ${value?'checked':''}></label>`;
export function propertiesHTML(E){const b=E.getBlock();if(!b)return '';const many=E.selection.size>1,ts=b.textStyle||{},image=['image','portrait'].includes(b.type);let s=`<div class="pro-panel"><details class="advanced-panel" open><summary>Transformação e organização</summary><div class="compact-grid">${field(many?'Girar seleção (Δ°)':'Rotação (°)',many?'groupRotation':'rotation',many?0:b.rotation||0)}${field('Opacidade','opacity',b.opacity??1,'number','min="0" max="1" step="0.05"')}</div>${check('Bloquear proporção','lockRatio',b.lockRatio)}<div class="pro-toolbar"><button data-pro="zero-rotation">Restaurar 0°</button><button data-pro="parent">Selecionar grupo superior</button><button data-pro="isolate">Isolar</button><button data-pro="restore-isolation">Sair do isolamento</button></div>${many?'<div class="pro-toolbar"><button data-pro="equal-w">Igualar larguras</button><button data-pro="equal-h">Igualar alturas</button><button data-pro="equal-size">Igualar tamanhos</button><button data-pro="lock-group">Bloquear seleção</button><button data-pro="hide-group">Ocultar seleção</button></div>':''}</details>`;
 if(!image&&b.type!=='separator'&&b.type!=='shape')s+=`<details class="advanced-panel"><summary>Tipografia e aparência</summary>${select('Família da fonte','textStyle.family',ts.family||'Arial',[...fontFamilies,...(E.doc.fonts||[]).map(f=>[f.family,f.name])])}<div class="compact-grid">${field('Tamanho','textStyle.size',ts.size||b.font,'number','min="8" max="250"')}${field('Cor do texto','textStyle.color',ts.color||b.textColor||'#deddd5','color')}${field('Espaço entre letras','textStyle.letterSpacing',ts.letterSpacing||0)}${field('Altura da linha','textStyle.lineHeight',ts.lineHeight||1.42,'number','min="0.8" max="4" step="0.05"')}${field('Margem interna','textStyle.padding',ts.padding||0,'number','min="0" max="200"')}${select('Vertical','textStyle.vertical',ts.vertical||'top',['top','middle','bottom'])}</div>${check('Negrito','textStyle.bold',ts.bold)}${check('Itálico','textStyle.italic',ts.italic)}${check('Sublinhado','textStyle.underline',ts.underline)}${check('Maiúsculas','textStyle.uppercase',ts.uppercase)}${field('Contorno','textStyle.outline',ts.outline||'#000000','color')}${check('Sombra','textStyle.shadow',ts.shadow)}${select('Fonte do título','titleStyle.family',b.titleStyle?.family||'Georgia',fontFamilies)}${field('Tamanho do título','titleStyle.size',b.titleStyle?.size||b.font+4,'number','min="8" max="250"')}${check('Título em negrito','titleStyle.bold',b.titleStyle?.bold!==false)}${check('Título em itálico','titleStyle.italic',b.titleStyle?.italic)}${field('Cor do título','titleStyle.color',b.titleStyle?.color||b.color||E.doc.accent||'#d1f49b','color')}<div class="pro-toolbar"><button data-pro="partial-text" ${textBinding(b,E.doc)?'':'disabled'}>Formatar trecho</button><button data-pro="import-font">Importar fonte local</button><button data-pro="fit-text">Aumentar altura</button><button data-pro="shrink-text">Reduzir fonte</button></div>${check('Ajuste automático de texto','autoFit',b.autoFit!==false)}</details>`;
 if(image){const a=b.imageAdjust||{},crop=b.crop||{x:0,y:0,w:1,h:1};s+=`<details class="advanced-panel" open><summary>Enquadramento e máscara</summary>${check('Arrastar conteúdo dentro da moldura','editImage',b.editImage)}<div class="compact-grid">${field('Zoom interno','imageZoom',b.imageZoom||1,'number','min="0.1" max="8" step="0.05"')}${field('Deslocamento X','imageX',b.imageX||0)}${field('Deslocamento Y','imageY',b.imageY||0)}${select('Máscara','mask',b.mask||'rectangle',[['rectangle','Retangular'],['circle','Circular'],['ellipse','Elíptica'],['shield','Escudo'],['diamond','Losango'],['arch','Arco']])}${field('Suavização (px)','softness',b.softness||0,'number','min="0" max="60"')}${field('Degradê (0–1)','fade',b.fade||0,'number','min="0" max="1" step="0.05"')}</div><p class="subtle">Recorte não destrutivo: frações de 0 a 1 da área original.</p><div class="compact-grid">${['x','y','w','h'].map(k=>field('Recorte '+k,'crop.'+k,crop[k],'number','min="0" max="1" step="0.01"')).join('')}</div>${check('Manter proporção do recorte','cropRatio',b.cropRatio)}<button class="pro-button" data-pro="reset-image">Restaurar imagem e enquadramento</button></details><details class="advanced-panel"><summary>Ajustes da imagem</summary><div class="compact-grid">${['brightness','contrast','saturation'].map(k=>field({brightness:'Brilho',contrast:'Contraste',saturation:'Saturação'}[k],'imageAdjust.'+k,a[k]??100,'number','min="0" max="200"')).join('')}${field('Temperatura','imageAdjust.temperature',a.temperature||0,'number','min="-100" max="100"')}${field('Tons de cinza (%)','imageAdjust.grayscale',a.grayscale||0,'number','min="0" max="100"')}</div></details>`;}
 if(['resource','resourceTrack','resourceValue'].includes(b.type))s+=select('Representação do recurso','resourceStyle',b.resourceStyle||'combined',[['combined','Combinado'],['number','Contador numérico'],['squares','Quadrados'],['circles','Círculos'],['bar','Barra horizontal']]);
 if(['attributes','skills'].includes(b.type))s+=`<details class="advanced-panel"><summary>Composição interna</summary>${select('Disposição','componentLayout',b.componentLayout||'vertical',['vertical','horizontal','grid'])}${field('Colunas','columns',b.columns||1,'number','min="1" max="4"')}${field('Espaçamento','rowGap',b.rowGap||0,'number','min="0" max="80"')}${select('Dados','dieStyle',b.dieStyle||'polygon',['polygon','circle','outline'])}</details>`;
 if(b.type==='attributeRow')s+=`<label>Valor do atributo<select data-attr="${b.attr}">${[4,6,8,10,12].map(n=>`<option value="${n}" ${E.doc.attrs[b.attr]===n?'selected':''}>d${n}</option>`).join('')}</select></label>`;if(b.type==='skillRow')s+=`<label>Valor da perícia<select data-skill="${b.skillKey}">${[4,6,8,10,12].map(n=>`<option value="${n}" ${(E.doc.skills[b.skillKey]||4)===n?'selected':''}>d${n}</option>`).join('')}</select></label>`;if(b.type==='attributeRow'||b.type==='skillRow')s+=field('Nome visual (preserva valor)','displayName',b.displayName||'','text');
 if(b.type==='shape')s+=`${select('Forma','shape',b.shape||'rectangle',['rectangle','circle','band','frame','icon'])}${field('Símbolo','symbol',b.symbol||'◆','text')}${field('Espessura da borda','strokeWidth',b.strokeWidth||2,'number','min="0" max="30"')}`;
 const overflow=E.measureOverflow(b);if(overflow?.overflow)s+=`<div class="overflow-note">O texto ultrapassa este bloco${b.autoFit!==false?' e será reduzido automaticamente':''}.<button data-pro="fit-text">Aumentar altura</button><button data-pro="shrink-text">Reduzir fonte</button></div>`;s+=`<div class="pro-toolbar"><button data-pro="copy-style">Copiar estilo</button><button data-pro="paste-style">Colar estilo</button><button data-pro="reset-style">Herdar tema</button><button data-pro="save-component">Salvar componente</button></div></div>`;return s;}
